Definition sc_segA_post (sp gp tp t0 t1 t2 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (bs ioc D N lo : Z) (ra s0 s1 s2 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' junk8 j16,
    ms' = MS (mkR (Z_to_bv 64 P_SC_RET1) (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2
                  (Z_to_bv 64 bs) (Z_to_bv 64 D) (Z_to_bv 64 bs) (Z_to_bv 64 (bv_unsigned sp + -104)) (Z_to_bv 64 0)
                  (Z_to_bv 64 (bv_unsigned sp + -104)) (Z_to_bv 64 T_ANYEX_PROP_FNS) a5 a6 a7
                  (Z_to_bv 64 N) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_SSVC_MAKE_IMPL) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -112)
    /\ rw_cells rsegs m' (bv_unsigned sp + -112) [CB 8 junk8]
    /\ rw_cells rsegs m' (bv_unsigned sp + -104) (AnyExecCells (bv_unsigned sp + -104) ioc j16)
    /\ rw_cells rsegs m' (bv_unsigned sp + -48) [C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.

