  0 <= ioc -> ioc + 24 <= 2^64 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 112 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (sc_segA_post sp gp tp t0 t1 t2 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc bs ioc D N lo ra s0 s1 s2 m)
