    (bs stb N lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m',
    ms' = MS (mkR (Z_to_bv 64 P_SC_RET2) (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 s0 s1
                  (Z_to_bv 64 (stb + 144)) (Z_to_bv 64 N) a2 a3 a4 a5 a6 a7
                  s2 (Z_to_bv 64 (stb + 32)) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_FB_PREPARE) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp + -112); (bs + 16, bs + 32)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -112)
    /\ rw_cells rsegs m' bs (BasicStreamCells stb).
